const color=/^#[0-9a-f]{6}$/i;
const finite=(v,name)=>{if(typeof v!=='number'||!Number.isFinite(v))throw Error(name+' must be a finite number.');return v};
export function validateRegionPatch(patch){const out={},numeric=['opacity','offsetX','offsetY','rotation','scale','position','angle','curve','start','fade'];for(const [k,v]of Object.entries(patch)){if(k==='color'){if(!color.test(v))throw Error('Use a six-digit hex color.');out[k]=v}else if(numeric.includes(k)){out[k]=finite(v,k);if(k==='opacity')out[k]=Math.max(0,Math.min(1,v));if(k==='scale'||k==='fade')out[k]=Math.max(.05,v)}else if(k==='blend'){if(!['color','multiply','screen','source-over'].includes(v))throw Error('Unsupported blend mode.');out[k]=v}else if(k==='points'){if(!Array.isArray(v)||v.length<3||v.length>500)throw Error('A polygon needs 3–500 points.');out[k]=v.map(p=>{if(!Array.isArray(p)||p.length!==2)throw Error('Use [u,v] coordinates.');return p.map(n=>Math.max(0,Math.min(1,finite(n,'coordinate'))))})}else throw Error('Unsupported region property: '+k)}return out}
export function validateTextLayer(layer){if(typeof layer.text!=='string'||layer.text.length>80)throw Error('Text must contain at most 80 characters.');const out={text:layer.text};for(const key of ['x','y','size','start','duration','depth','rotation','blur','whiteStart','whiteDuration','whiteGlyphStart','whiteGlyphEnd'])if(key in layer){out[key]=finite(layer[key],key);if(['size','duration','whiteDuration'].includes(key))out[key]=Math.max(.1,out[key])}for(const key of ['color','whiteColor'])if(key in layer){if(!color.test(layer[key]))throw Error('Use a six-digit hex ink color.');out[key]=layer[key]}if(layer.frontContrast!=null){if(typeof layer.frontContrast!=='boolean')throw Error('frontContrast must be boolean.');out.frontContrast=layer.frontContrast}if(layer.anchor!=null){if(!['people','scene'].includes(layer.anchor))throw Error('Unknown text anchor.');out.anchor=layer.anchor}if(layer.order!=null){if(!['front','behind','under-head'].includes(layer.order))throw Error('Unknown text layer order.');out.order=layer.order}if(layer.style!=null){if(!['brush','ink','chalk'].includes(layer.style))throw Error('Unknown pen style.');out.style=layer.style}if(layer.whiteMode!=null){if(!['none','silhouette','wipe','full','glyph-spread'].includes(layer.whiteMode))throw Error('Unknown white takeover mode.');out.whiteMode=layer.whiteMode}return out}
export function validateImageMotion(input){const out={},allowed=['cityDuration','cityFlyTime','cityStartU','cityStartV','cityEndU','cityEndV','cityStartDistance','cityEndDistance','cityStartElevation','cityEndElevation','cityHeading','cityRoll','cityEndRoll','citySpinStart','citySpinTime','cityTurns','cityEdgeBlur'];for(const [k,v]of Object.entries(input)){if(!allowed.includes(k))throw Error('Unsupported image motion parameter: '+k);out[k]=finite(v,k);if(['cityDuration','cityFlyTime','cityStartDistance','cityEndDistance','citySpinTime'].includes(k))out[k]=Math.max(.1,v)}return out}
